sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if (!transformBuilder) return;

        var listModel = transformBuilder

        // do not remove
        .transform();

        // Use your actual comments field name
        var editableField = 'comments'; 
        // If actual field is u_comments, use:
        // var editableField = 'u_comments';

        // Make only Comments column editable
        if (listModel.columnDefinitions && listModel.columnDefinitions.columns) {
            listModel.columnDefinitions.columns.forEach(function(column) {
                var isComments = column.key === editableField;

                column.editable = isComments;
                column.readOnly = !isComments;
                column.disabled = !isComments;
            });
        }

        // Make only Comments cells editable
        if (listModel.rowDefinitions && listModel.rowDefinitions.rows) {
            listModel.rowDefinitions.rows.forEach(function(row) {
                if (!row.cells) return;

                Object.keys(row.cells).forEach(function(cellKey) {
                    var cell = row.cells[cellKey];
                    var isComments = cellKey === editableField;

                    cell.editable = isComments;
                    cell.readOnly = !isComments;
                    cell.disabled = !isComments;
                });
            });
        }

        return listModel;
    }

    catch (error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
